--- tools/test_sf32lb52_audio_hil.py ---
import unittest

from sf32lb52_audio_hil import encode_nsh_command, remote_script


class AudioHilCommandTests(unittest.TestCase):
    def test_nsh_command_uses_crlf(self):
        self.assertEqual(encode_nsh_command("velawear music"), b"velawear music\r\n")

    def test_nsh_command_rejects_non_ascii(self):
        with self.assertRaises(ValueError):
            encode_nsh_command("velawear 女友")

    def test_remote_script_writes_encoded_command(self):
        script = remote_script(45, "velawear music", 15, "/dev/ttyUSB1")
        self.assertIn("command_bytes = b'velawear music\\r\\n'", script)
        self.assertIn("os.write(fd, command_bytes)", script)


if __name__ == "__main__":
    unittest.main()

