    54	                         char *response, size_t response_size)
    55	{
    56	  int ret;
    57	
    58	  if (llm == NULL || !llm->initialized || prompt == NULL ||
    59	      response == NULL || response_size == 0)
    60	    {
    61	      return VELAWEAR_ERR_INVAL;
    62	    }
    63	
    64	  llm->request_count++;
    65	
    66	  ret = velawear_ble_request_llm(prompt, response, response_size, 15000);
    67	  if (ret == 0 && response[0] != '\0')
    68	    {
    69	      llm->connected = true;
    70	      syslog(LOG_INFO, "[LLM] request=%d cloud_bridge connected=1\n",
    71	             llm->request_count);
    72	      return VELAWEAR_OK;
    73	    }
    74	
    75	  llm->connected = false;
    76	
    77	  /* The BLE bridge may be absent, disconnected, or unable to reach its
    78	   * configured cloud endpoint. Keep the Agent usable offline with short,
    79	   * warm companion replies instead of dropping a CALL_LLM action. */
    80	  if (strstr(prompt, "陪") != NULL || strstr(prompt, "聊") != NULL ||
