   753	    }
   754	
   755	  g_audio_dma_codec = &codec;
   756	  g_audio_dma_complete = false;
   757	  g_audio_dma_error = false;
   758	  ret = HAL_AUDCODEC_Transmit_DMA(
   759	          &codec, (uint8_t *)g_audio_dma_buffer,
   760	          samples * sizeof(uint32_t), HAL_AUDCODEC_DAC_CH0);
   761	  if (ret != HAL_OK)
   762	    {
   763	      syslog(LOG_ERR, "[AudioVoice] DMA start failed: %d\n", ret);
   764	      g_audio_dma_codec = NULL;
   765	      goto cleanup_dac;
   766	    }
   767	
   768	#if VELAWEAR_ENABLE_EXTERNAL_PA
   769	  audio_pa_set(true);
   770	#else
   771	  audio_pa_set(false);
   772	  syslog(LOG_WARNING,
   773	         "[AudioVoice] external PA disabled after reset-safe HIL\n");
   774	#endif
   775	  HAL_Delay_us(30000);
   776	  HAL_AUDCODEC_Config_DACPath(&codec, 0);
   777	
   778	  for (waited = 0; waited < duration_ms + 500U; waited++)
   779	    {
   780	      if (g_audio_dma_complete || g_audio_dma_error)
   781	        {
   782	          break;
   783	        }
   784	      usleep(1000);
   785	    }
   786	
   787	  if (!g_audio_dma_complete || g_audio_dma_error)
   788	    {
   789	      ret = g_audio_dma_error ? HAL_ERROR : HAL_TIMEOUT;
   790	      syslog(LOG_WARNING, "[AudioVoice] DMA %s after %lu ms\n",
   791	             g_audio_dma_error ? "error" : "timeout",
   792	             (unsigned long)waited);
   793	    }
   794	  else
   795	    {
   796	      syslog(LOG_INFO, "[AudioVoice] DMA complete\n");
   797	    }
   798	  g_audio_dma_codec = NULL;
   799	
   800	  audio_pa_set(false);
   801	
   802	cleanup_dac:
   803	  audio_dac_stop(&codec);
   804	cleanup_codec:
   805	  HAL_AUDCODEC_DeInit(&codec);
   806	  HAL_TURN_OFF_PLL();
   807	cleanup_power:
   808	  HAL_PMU_EnableAudio(0);
   809	  syslog(ret == HAL_OK ? LOG_INFO : LOG_WARNING,
   810	         "[AudioVoice] speaker voice %s (stream=%u, samples=%lu)\n",
   811	         ret == HAL_OK ? "played" : "failed",
   812	         (unsigned int)g_audio_voice_stream_id, (unsigned long)samples);
   813	  return ret == HAL_OK ? 0 : -1;
   814	}
   815	
  1135	  syslog(LOG_INFO, "[AudioTest] complete\n");
  1136	  return ret == HAL_OK ? 0 : -1;
  1137	}
