  1139	int velawear_audio_voice_start(uint16_t stream_id,
  1140	                               uint32_t sample_count,
  1141	                               uint32_t total_bytes,
  1142	                               uint32_t crc32)
  1143	{
  1144	  int ret = 0;
  1145	
  1146	  pthread_mutex_lock(&g_audio_hw_lock);
  1147	  if (g_audio_voice_receiving || g_audio_voice_ready ||
  1148	      g_audio_voice_playing)
  1149	    {
  1150	      ret = -1;
  1151	    }
  1152	  else if (sample_count == 0 || sample_count > AUDIO_DMA_BUFFER_WORDS ||
  1153	           total_bytes != sample_count * 2U ||
  1154	           total_bytes > VELAWEAR_AGENT_AUDIO_MAX_PCM_BYTES)
  1155	    {
  1156	      ret = -1;
  1157	    }
  1158	  else
  1159	    {
  1160	      g_audio_voice_receiving = true;
  1161	      g_audio_voice_ready = false;
  1162	      g_audio_voice_stream_id = stream_id;
  1163	      g_audio_voice_expected_bytes = total_bytes;
  1164	      g_audio_voice_received_bytes = 0;
  1165	      g_audio_voice_sample_count = sample_count;
  1166	      g_audio_voice_expected_crc32 = crc32;
  1167	      g_audio_voice_crc32 = 0xffffffffU;
  1168	    }
  1169	  pthread_mutex_unlock(&g_audio_hw_lock);
  1170	
  1171	  if (ret < 0)
  1172	    {
  1173	      syslog(LOG_WARNING,
  1174	             "[AudioVoice] reject start stream=%u samples=%lu bytes=%lu\n",
  1175	             (unsigned int)stream_id, (unsigned long)sample_count,
  1176	             (unsigned long)total_bytes);
  1177	    }
  1178	  return ret;
  1179	}
  1180	
  1181	int velawear_audio_voice_write(uint16_t stream_id,
  1182	                               uint32_t offset,
  1183	                               const uint8_t *data,
  1184	                               uint16_t length)
  1185	{
  1186	  uint16_t i;
  1187	  int ret = 0;
  1188	
  1189	  pthread_mutex_lock(&g_audio_hw_lock);
  1190	  if (!g_audio_voice_receiving || stream_id != g_audio_voice_stream_id ||
  1191	      data == NULL || length == 0 || (length & 1U) != 0U ||
  1192	      offset != g_audio_voice_received_bytes ||
  1193	      offset > g_audio_voice_expected_bytes ||
  1194	      length > g_audio_voice_expected_bytes - offset)
  1195	    {
  1196	      ret = -1;
  1197	    }
  1198	  else
  1199	    {
  1200	      for (i = 0; i < length; i += 2)
  1201	        {
  1202	          uint16_t sample = (uint16_t)data[i] |
  1203	                            ((uint16_t)data[i + 1] << 8);
  1204	          g_audio_dma_buffer[(offset + i) / 2U] = (uint32_t)sample;
  1205	        }
  1206	      g_audio_voice_crc32 = audio_crc32_update(g_audio_voice_crc32,
  1207	                                                data, length);
  1208	      g_audio_voice_received_bytes += length;
  1209	    }
  1210	  pthread_mutex_unlock(&g_audio_hw_lock);
  1211	
  1212	  return ret;
  1213	}
