  1215	int velawear_audio_voice_end(uint16_t stream_id,
  1216	                             uint32_t total_bytes,
  1217	                             uint32_t crc32,
  1218	                             uint32_t *sample_count)
  1219	{
  1220	  uint32_t actual_crc32;
  1221	  int ret = 0;
  1222	
  1223	  pthread_mutex_lock(&g_audio_hw_lock);
  1224	  if (!g_audio_voice_receiving || stream_id != g_audio_voice_stream_id ||
  1225	      total_bytes != g_audio_voice_expected_bytes ||
  1226	      g_audio_voice_received_bytes != g_audio_voice_expected_bytes)
  1227	    {
  1228	      ret = -1;
  1229	    }
  1230	  else
  1231	    {
  1232	      actual_crc32 = g_audio_voice_crc32 ^ 0xffffffffU;
  1233	      if (actual_crc32 != g_audio_voice_expected_crc32 ||
  1234	          actual_crc32 != crc32)
  1235	        {
  1236	          ret = -1;
  1237	        }
  1238	      else
  1239	        {
  1240	          g_audio_voice_receiving = false;
  1241	          g_audio_voice_ready = true;
  1242	          if (sample_count != NULL)
  1243	            {
  1244	              *sample_count = g_audio_voice_sample_count;
  1245	            }
  1246	          syslog(LOG_INFO,
  1247	                 "[AudioVoice] stream complete id=%u samples=%lu bytes=%lu\n",
  1248	                 (unsigned int)stream_id,
  1249	                 (unsigned long)g_audio_voice_sample_count,
  1250	                 (unsigned long)g_audio_voice_expected_bytes);
  1251	        }
  1252	    }
  1253	
  1254	  if (ret < 0)
  1255	    {
  1256	      g_audio_voice_receiving = false;
  1257	      g_audio_voice_ready = false;
  1258	      syslog(LOG_WARNING,
  1259	             "[AudioVoice] stream rejected id=%u received=%lu expected=%lu\n",
  1260	             (unsigned int)stream_id,
  1261	             (unsigned long)g_audio_voice_received_bytes,
  1262	             (unsigned long)g_audio_voice_expected_bytes);
  1263	    }
  1264	  pthread_mutex_unlock(&g_audio_hw_lock);
  1265	  return ret;
  1266	}
