  1268	int velawear_audio_voice_play(uint16_t stream_id, uint32_t sample_count)
  1269	{
  1270	  bool resume_stream = false;
  1271	  int ret;
  1272	
  1273	  pthread_mutex_lock(&g_audio_hw_lock);
  1274	  if (!g_audio_voice_ready || g_audio_voice_playing ||
  1275	      stream_id != g_audio_voice_stream_id ||
  1276	      sample_count != g_audio_voice_sample_count)
  1277	    {
  1278	      pthread_mutex_unlock(&g_audio_hw_lock);
  1279	      return -1;
  1280	    }
  1281	
  1282	  g_audio_voice_ready = false;
  1283	  g_audio_voice_playing = true;
  1284	  resume_stream = audio_mic_stream_suspend_locked();
  1285	  ret = audio_voice_play_locked(sample_count);
  1286	  audio_mic_stream_resume_locked(resume_stream);
  1287	  g_audio_voice_playing = false;
  1288	  if (ret == 0)
  1289	    {
  1290	      g_audio_voice_received_bytes = 0;
  1291	      g_audio_voice_expected_bytes = 0;
  1292	      g_audio_voice_sample_count = 0;
  1293	    }
  1294	  pthread_mutex_unlock(&g_audio_hw_lock);
  1295	
  1296	  return ret;
  1297	}
